		fmt.Fprintf(os.Stderr, "syscli: %v\n", err)
		os.Exit(1)
	}
	used := total - free

	if *human {
		fmt.Printf("path %s: total %s, used %s, free %s\n",
			*path, humanize(total), humanize(used), humanize(free))
		return
	}
	fmt.Printf("path %s: total=%d used=%d free=%d bytes\n", *path, total, used, free)
}

func humanize(n uint64) string {
	const unit = 1024
	if n < unit {
		return fmt.Sprintf("%d B", n)
	}
	div, exp := uint64(unit), 0
	for m := n / unit; m >= unit; m /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f %ciB", float64(n)/float64(div), "KMGTPE"[exp])
}

// Package disk reports filesystem statistics using platform system calls that
// are not exposed by the Go standard library.
//
// The exported API is declared in platform-specific files, each guarded by a
// build constraint:
//
//	disk_unix.go     //go:build linux || darwin
//	disk_windows.go  //go:build windows
//	disk_other.go    //go:build !linux && !darwin && !windows
//
// Adding another raw system call follows the same shape: declare the exported
// function once per supported platform, and provide an unsupported fallback so
// the package still compiles everywhere.
//
// Prefer the typed wrappers in golang.org/x/sys. When a call has no wrapper,
// invoke it directly:
//
//   - Linux/macOS: unix.Syscall, unix.Syscall6 or unix.RawSyscall with the
//     SYS_* constant, or unix.Sysctl for macOS/BSD kernel parameters.
//   - Windows: windows.NewLazySystemDLL("...").
//     NewProc("...").Call(...) for calls without a generated wrapper.
package disk

import "errors"

// ErrUnsupported reports that the current operating system has no
// implementation of an operation.
var ErrUnsupported = errors.New("disk: operation not supported on this platform")

//go:build linux || darwin

package disk

import "golang.org/x/sys/unix"

// Free returns the total and free bytes of the filesystem that contains path.
// It is implemented with the statfs(2) system call via golang.org/x/sys/unix.
func Free(path string) (total, free uint64, err error) {
	var st unix.Statfs_t
	if err := unix.Statfs(path, &st); err != nil {
		return 0, 0, err
	}
	bsize := uint64(st.Bsize)
	return st.Blocks * bsize, st.Bavail * bsize, nil
}

//go:build windows

package disk

import "golang.org/x/sys/windows"

// Free returns the total and free bytes of the volume that contains path.
// It is implemented with the GetDiskFreeSpaceEx Win32 API via
// golang.org/x/sys/windows.
func Free(path string) (total, free uint64, err error) {
	name, err := windows.UTF16PtrFromString(path)
	if err != nil {
		return 0, 0, err
	}
	var freeToCaller, totalBytes, totalFree uint64
	if err := windows.GetDiskFreeSpaceEx(name, &freeToCaller, &totalBytes, &totalFree); err != nil {
		return 0, 0, err
	}
	return totalBytes, totalFree, nil
}

//go:build !linux && !darwin && !windows

package disk

// Free is not implemented on this platform.
func Free(path string) (total, free uint64, err error) {
	return 0, 0, ErrUnsupported
}

//go:build linux || darwin || windows

package disk

import "testing"

func TestFree(t *testing.T) {
	total, free, err := Free(".")
	if err != nil {
		t.Fatalf("Free(.): %v", err)
	}
	if total == 0 {
		t.Error("total = 0, want > 0")
	}
	if free > total {
		t.Errorf("free %d > total %d", free, total)
	}
}

//go:build !linux && !darwin && !windows

package disk

import "testing"

func TestFreeUnsupported(t *testing.T) {
	if _, _, err := Free("."); err != ErrUnsupported {
		t.Fatalf("Free(.) error = %v, want ErrUnsupported", err)
	}
}

